// ...
export default new bp.Integration({
// ...previously implemented logic
handler: async ({ req, client: botpressClient, ctx, logger }) => {
const liveAgentEvent = JSON.parse(req.body);
switch (liveAgentEvent.eventType) {
case 'newMessage':
// ...
break;
case 'ticketAssigned':
